CREATE FUNCTION gov_private.gov_dossie_gestor(p_employee uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.gov_is_rh_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.gov_cadeia_hierarquica(p_employee) h WHERE h.employee_id=public.gov_meu_employee())) $$;
CREATE FUNCTION public.gov_dossie_gestor(p_employee uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT gov_private.gov_dossie_gestor(p_employee) $$;
REVOKE ALL ON FUNCTION gov_private.gov_dossie_gestor(uuid),public.gov_dossie_gestor(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION gov_private.gov_dossie_gestor(uuid),public.gov_dossie_gestor(uuid) TO authenticated,service_role;
CREATE TABLE public.gov_dossie_registros(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid NOT NULL REFERENCES public.employees(id),tipo text NOT NULL,titulo text NOT NULL,conteudo text NOT NULL,ocorrido_em timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'registrado',confidencial boolean NOT NULL DEFAULT false,anexos jsonb NOT NULL DEFAULT '[]',original_id uuid REFERENCES public.gov_dossie_registros(id),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.gov_dossie_registros TO authenticated;
GRANT ALL ON public.gov_dossie_registros TO service_role;
ALTER TABLE public.gov_dossie_registros ENABLE ROW LEVEL SECURITY;
CREATE POLICY gov_dossie_ler ON public.gov_dossie_registros FOR SELECT TO authenticated USING(public.gov_dossie_gestor(employee_id) OR (employee_id=public.gov_meu_employee() AND NOT confidencial));
CREATE POLICY gov_dossie_criar ON public.gov_dossie_registros FOR INSERT TO authenticated WITH CHECK(public.gov_dossie_gestor(employee_id) AND created_by=auth.uid());
CREATE POLICY gov_dossie_editar ON public.gov_dossie_registros FOR UPDATE TO authenticated USING(public.gov_dossie_gestor(employee_id) AND (created_by=auth.uid() OR public.gov_is_rh_admin(auth.uid()))) WITH CHECK(public.gov_dossie_gestor(employee_id));
CREATE INDEX ON public.gov_dossie_registros(employee_id,ocorrido_em DESC);
CREATE TABLE public.gov_dossie_ciencias(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),registro_id uuid NOT NULL UNIQUE REFERENCES public.gov_dossie_registros(id),user_id uuid NOT NULL DEFAULT auth.uid(),decisao text NOT NULL,comentario text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.gov_dossie_ciencias TO authenticated;
GRANT ALL ON public.gov_dossie_ciencias TO service_role;
ALTER TABLE public.gov_dossie_ciencias ENABLE ROW LEVEL SECURITY;
CREATE POLICY gov_ciencia_ler ON public.gov_dossie_ciencias FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.gov_dossie_registros r WHERE r.id=registro_id));
CREATE POLICY gov_ciencia_criar ON public.gov_dossie_ciencias FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.gov_dossie_registros r WHERE r.id=registro_id AND r.employee_id=public.gov_meu_employee() AND NOT r.confidencial));
CREATE FUNCTION public.gov_dossie_validar() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE orig public.gov_dossie_registros; a jsonb; BEGIN
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Registros do dossiê não podem ser excluídos'; END IF;
IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid();NEW.created_at:=now(); ELSE
IF now() >= OLD.created_at+interval '24 hours' THEN RAISE EXCEPTION 'Registro imutável após 24 horas. Acrescente um adendo.';END IF;
IF EXISTS(SELECT 1 FROM public.gov_dossie_ciencias WHERE registro_id=OLD.id) THEN RAISE EXCEPTION 'Registro com ciência ou recusa é imutável'; END IF;
IF NEW.id<>OLD.id OR NEW.employee_id<>OLD.employee_id OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.original_id IS DISTINCT FROM OLD.original_id THEN RAISE EXCEPTION 'Identidade do registro é imutável'; END IF;
END IF;
IF NEW.tipo NOT IN ('one_on_one','feedback','yellow_flag','red_flag','pdi','adendo') OR length(trim(NEW.titulo))=0 OR length(trim(NEW.conteudo))=0 OR length(NEW.titulo)>200 OR length(NEW.conteudo)>20000 THEN RAISE EXCEPTION 'Preencha tipo, título e conteúdo válidos'; END IF;
IF NEW.ocorrido_em>now() THEN RAISE EXCEPTION 'Data não pode ser futura'; END IF;
IF NEW.status NOT IN ('registrado','aberta','resolvida','nao_iniciado','em_andamento','concluido','cancelado') THEN RAISE EXCEPTION 'Status inválido'; END IF;
IF NEW.tipo IN ('yellow_flag','red_flag') AND NEW.status NOT IN ('aberta','resolvida') THEN RAISE EXCEPTION 'Flag deve estar aberta ou resolvida'; END IF;
IF NEW.tipo='pdi' AND NEW.status NOT IN ('nao_iniciado','em_andamento','concluido','cancelado') THEN RAISE EXCEPTION 'Status de PDI inválido';END IF;
IF NEW.tipo IN ('one_on_one','feedback','adendo') AND NEW.status<>'registrado' THEN RAISE EXCEPTION 'Status do registro inválido';END IF;
IF (NEW.tipo='adendo')<>(NEW.original_id IS NOT NULL) THEN RAISE EXCEPTION 'Adendo deve referenciar o original'; END IF;
IF NEW.original_id IS NOT NULL THEN SELECT * INTO orig FROM public.gov_dossie_registros WHERE id=NEW.original_id;IF NOT FOUND OR orig.employee_id<>NEW.employee_id OR orig.tipo='adendo' THEN RAISE EXCEPTION 'Original inválido'; END IF; NEW.confidencial:=orig.confidencial;END IF;
IF TG_OP='UPDATE' AND OLD.confidencial AND NOT NEW.confidencial AND EXISTS(SELECT 1 FROM public.gov_dossie_registros WHERE original_id=OLD.id) THEN RAISE EXCEPTION 'Confidencialidade não pode mudar após adendos'; END IF;
IF TG_OP='UPDATE' AND NEW.confidencial IS DISTINCT FROM OLD.confidencial AND EXISTS(SELECT 1 FROM public.gov_dossie_registros WHERE original_id=OLD.id) THEN RAISE EXCEPTION 'Confidencialidade não pode mudar após adendos'; END IF;
IF jsonb_typeof(NEW.anexos)<>'array' OR jsonb_array_length(NEW.anexos)>10 THEN RAISE EXCEPTION 'Anexos inválidos'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(NEW.anexos) LOOP IF a->>'path' NOT LIKE NEW.id::text || '/%' OR coalesce(a->>'nome','')='' THEN RAISE EXCEPTION 'Caminho de anexo inválido'; END IF;END LOOP;
NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER gov_dossie_validacao BEFORE INSERT OR UPDATE OR DELETE ON public.gov_dossie_registros FOR EACH ROW EXECUTE FUNCTION public.gov_dossie_validar();
CREATE FUNCTION public.gov_dossie_ciencia_validar() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Ciência é imutável';END IF; IF NEW.decisao NOT IN ('ciente','recusou') OR length(NEW.comentario)>5000 THEN RAISE EXCEPTION 'Ciência inválida';END IF;NEW.user_id:=auth.uid();NEW.created_at:=now();NEW.updated_at:=now();RETURN NEW;END $$;
CREATE TRIGGER gov_dossie_ciencia_validacao BEFORE INSERT OR UPDATE OR DELETE ON public.gov_dossie_ciencias FOR EACH ROW EXECUTE FUNCTION public.gov_dossie_ciencia_validar();
REVOKE ALL ON FUNCTION public.gov_dossie_validar(),public.gov_dossie_ciencia_validar() FROM PUBLIC,anon;
CREATE FUNCTION public.gov_dossie_anexo_permitido(p_nome text,p_escrita boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.gov_dossie_registros r WHERE r.id::text=split_part(p_nome,'/',1) AND CASE WHEN p_escrita THEN public.gov_dossie_gestor(r.employee_id) AND (r.created_by=auth.uid() OR public.gov_is_rh_admin(auth.uid())) AND now()<r.created_at+interval '24 hours' AND NOT EXISTS(SELECT 1 FROM public.gov_dossie_ciencias c WHERE c.registro_id=r.id) ELSE EXISTS(SELECT 1 FROM jsonb_array_elements(r.anexos) a WHERE a->>'path'=p_nome) END) $$;
REVOKE ALL ON FUNCTION public.gov_dossie_anexo_permitido(text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.gov_dossie_anexo_permitido(text,boolean) TO authenticated,service_role;
CREATE POLICY gov_dossie_storage_ler ON storage.objects FOR SELECT TO authenticated USING(bucket_id='rh-dossie-evidencias' AND public.gov_dossie_anexo_permitido(name,false));
CREATE POLICY gov_dossie_storage_criar ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='rh-dossie-evidencias' AND public.gov_dossie_anexo_permitido(name,true));